async function request(body?:any):Promise<any>{const r=await fetch('/api/erp',body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const data:any=await r.json();if(r.status===428){location.assign('/password');throw Error('비밀번호를 변경해 주세요.')}if(r.status===401){location.assign('/login');throw Error('로그인해 주세요.')}if(!r.ok)throw Error(data.error||'처리하지 못했습니다.');return data}
function Field({label,children,hint}:any){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Pick({value,onChange,items,label}:any){return <Select value={value} onValueChange={onChange}><SelectTrigger className="pick" aria-label={label}><SelectValue>{items.find((i:any)=>(typeof i==='string'?i:i.value)===value)?.label||value||'선택'}</SelectValue></SelectTrigger><SelectContent>{items.map((i:any)=><SelectItem key={typeof i==='string'?i:i.value} value={typeof i==='string'?i:i.value}>{typeof i==='string'?i:i.label}</SelectItem>)}</SelectContent></Select>}
function Blank({title='등록된 업무가 없습니다',text='지시와 완료 기준을 등록하면 여기에서 진행 상황을 확인할 수 있습니다.'}:any){return <Empty><EmptyHeader><EmptyTitle>{title}</EmptyTitle><EmptyDescription>{text}</EmptyDescription></EmptyHeader></Empty>}
function Stamp({status}:any){return <span className={'stamp '+(status==='완료'?'done':status?.includes('판단')?'decision':status==='응답 대기'?'waiting':'')}>{status}</span>}
function dateText(value:string){if(!value)return '미정';return value.replace('T',' ').slice(0,16)}
function overdue(t:Task){return !!t.data.due&&new Date(t.data.due).getTime()<Date.now()&&!['완료','보류'].includes(t.data.status)}
function waitAge(value:string){if(!value)return '';const hours=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/3600000));return hours<24?`${hours}시간 대기`:`${Math.floor(hours/24)}일 대기`}
