 {BOARD_TABS[tab]&&((area==='DO'&&isDO)||(area==='OS'&&['wording','meeting','seminar','skill'].includes(BOARD_TABS[tab]))||(area==='SS'&&BOARD_TABS[tab]==='order'))&&<ManagementBoard key={area+tab} category={BOARD_TABS[tab]} member={member}/>}
