 {dssActive&&isDO&&['finance','personnel','legal','protection','general','assets','contracts','dispute','ip','privacy','procure','calendar'].includes(tab.slice(3))&&tab.startsWith('ER:')&&<DssOperations key={tab} section={tab.slice(3)} records={rows} onNavigate={navigateTool} onTask={setSelected} onNewTask={openTask}/>}
 {dssActive&&isDO&&tab.startsWith('ER:')&&!['home','finance','personnel','legal','protection','general','assets','contracts','dispute','ip','privacy','procure','calendar'].includes(tab.slice(3))&&<DssStrategy key={tab} initialAgendaId={directorAgenda} section={tab==='ER:strategy'?'home':tab.slice(3)} state={state} onNavigate={navigateTool} onTask={setSelected}/>}

